package common

import("bytes";"encoding/json";"fmt";"net/http";"strings")
type SlackAdapter struct{Token string;Client *http.Client}
func(a SlackAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){event:=payload;if nested,ok:=payload["event"].(map[string]any);ok{event=nested};user,_:=event["user"].(string);if user==""{user,_=event["user_id"].(string)};channel,_:=event["channel"].(string);if channel==""{channel,_=event["channel_id"].(string)};if user==""||channel==""{return InboundEvent{},fmt.Errorf("Slack event has no user or channel")};result:=InboundEvent{Platform:"slack",UserID:user,ReplyTarget:channel,ContentType:"text"};result.Text,_=event["text"].(string);if files,ok:=event["files"].([]any);ok&&len(files)>0{file,_:=files[0].(map[string]any);result.MediaURL,_=file["url_private"].(string);result.ContentType=slackContentType(fmt.Sprint(file["mimetype"]),fmt.Sprint(file["name"]))};return result,nil}
func slackContentType(mime,name string)string{value:=strings.ToLower(mime+" "+name);if strings.HasPrefix(value,"image/"){return"image"};if strings.HasPrefix(value,"audio/"){return"audio"};if strings.HasPrefix(value,"video/"){return"video"};return"file"}
func(a SlackAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{data,_:=json.Marshal(map[string]any{"channel":event.ReplyTarget,"text":message.Text});req,_:=http.NewRequest(http.MethodPost,"https://slack.com/api/chat.postMessage",bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};var result map[string]any;json.NewDecoder(resp.Body).Decode(&result);resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Slack HTTP returned %s",resp.Status)};if ok,_:=result["ok"].(bool);!ok{return fmt.Errorf("Slack API error: %v",result["error"])}};return nil}
